        public static Texture2D Build()
        {
            var tex = new Texture2D(Width, Height, TextureFormat.RGBA32, false, true)
            {
                name = "Authored Water Color Field",
                wrapMode = TextureWrapMode.Clamp,
                filterMode = FilterMode.Bilinear
            };

            var pixels = new Color32[Width * Height];
            int cursor = 0;
            string[] runs = Rle.Split(',');
            for (int i = 0; i < runs.Length; i++)
            {
                string[] parts = runs[i].Split(':');
                int count = int.Parse(parts[0]);
                int index = int.Parse(parts[1]);
                Color32 color = Palette[index];
                for (int j = 0; j < count && cursor < pixels.Length; j++)
                    pixels[cursor++] = color;
            }

            if (cursor != pixels.Length)
                throw new InvalidOperationException($"Authored color RLE decoded {cursor} pixels; expected {pixels.Length}.");

            for (int y = 0; y < Height / 2; y++)
            {
                int other = Height - 1 - y;
                for (int x = 0; x < Width; x++)
                {
                    int a = y * Width + x;
                    int b = other * Width + x;
                    Color32 t = pixels[a]; pixels[a] = pixels[b]; pixels[b] = t;
                }
            }

            tex.SetPixels32(pixels);
            tex.Apply(false, false);
            return tex;
        }
    }
